    diagonals = []
    for i in range(n):
        for j in range(i + 2, n):
            if i == 0 and j == n - 1: continue
            diagonals.append((i, j))

    max_size = 0
    def backtrack(index, current_subset):
        nonlocal max_size
        if index == len(diagonals):
            max_size = max(max_size, len(current_subset))
            return

        # Option 1: Include diagonals[index]
        d = diagonals[index]
        can_add = True
        for existing_d in current_subset:
            if not is_non_crossing(d[0], d[1], existing_d[0], existing_d[1]):
